    """
    K3 internal coverage only. Any unfulfilled requirement not supplied by
    either of the other two committed constituents remains externally exposed.
    """
    exposed=0
    for i,m in enumerate(ms):
        if not requires_external(m):
            continue
        supplied_by_internal=0
        for j,q in enumerate(ms):
            if j!=i and q is not None:
                supplied_by_internal |= q[4]
        exposed |= (m[3] & ~supplied_by_internal)
    return exposed & 0x3F",
