      "succ_source": "def succ(state):
    """Exact selected K3+leaf successors under validated no-omega + M_R."""
    ans=succ_cache.get(state)
    if ans is not None:
        return ans

    opts=[[None]+moves[s] for s in state]
    best=-1
    selected=collections.defaultdict(set)

    for ms in itertools.product(*opts):
        if all(m is None for m in ms):
            continue

        lawful=True
        for i,m in enumerate(ms):
            if not req(m):
                continue
            supplied=0
            for j in ADJ[i]:
                q=ms[j]
                if q is not None:
                    supplied |= q[4]
            if not (m[3] & supplied):
                lawful=False
                break
        if not lawful:
            continue

        dest=[state[i] if m is None else m[0] for i,m in enumerate(ms)]
        dstate=(dest[0],)+tuple(sorted(dest[1:3]))+(dest[3],)
        score=min(ranks[x] for x in dstate)

        label=0
        for m in ms:
            if m is not None:
                label |= m[4]

        if score>best:
            best=score
            selected=collections.defaultdict(set)
            selected[label].add(dstate)
        elif score==best:
            selected[label].add(dstate)

    ans={k:tuple(sorted(v)) for k,v in selected.items()}
    succ_cache[state]=ans
    return ans"
    },
